 Cai觉得有必要重温的题目.jpg
解答均为Cai自己写的，不代表最优解
PTA # 1. L1-002 打印沙漏 # 思路：先用模拟求一下需要使用的符号和层数，然后再输出即可
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; char c; cin &gt;&gt; n &gt;&gt; c; int req=0; int l=1; while (2*l*l-1&lt;=n) { l++; } l--; req = 2*l*l-1; for (int i=l;i&gt;=1;i--) { cout &lt;&lt; string(l-i,&#39; &#39;) &lt;&lt; string(2*i-1,c) &lt;&lt; &#39;\n&#39;; } for (int i=2;i&lt;=l;i++) { cout &lt;&lt; string(l-i,&#39; &#39;) &lt;&lt; string(2*i-1,c) &lt;&lt; &#39;\n&#39;; } cout &lt;&lt; n-req; } 2. L1-006 连续因子 # 思路：从2为开头，长度len寻找满足条件的因数列(n%因数积==0)，坑是遇到质数，因数是他本身
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { ll n; cin &gt;&gt; n; ll head=0,len=0; for (ll i=2;i*i&lt;=n;i++) { for (ll l=len;;l++) { ll s=1; for (ll k=0;k&lt;l;k++) { s*=i+k; } if (s&gt;n) { break; } if (n%s==0&amp;&amp;l&gt;len) { head=i; len=l; } } } if (len==0) { len=1; head=n; } cout &lt;&lt; len &lt;&lt; &#39;\n&#39;; string sep; for (ll k=0;k&lt;len;k++) { cout &lt;&lt; sep &lt;&lt; head+k; sep=&#34;*&#34;; } } 3. L1-009 N个数求和 # 思路：定义一个和的分子分母a、b，然后用公式去算，最后用__gcd()求最大公约数化简，坑是有一个测试点是0，要单独处理
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; ll a=0,b=1; for (int i=0;i&lt;n;i++) { int x,y; scanf(&#34;%d/%d&#34;,&amp;x,&amp;y); a=a*y+x*b; b=b*y; // a x a*y+x*b // - + - = ------- // b y b*y } if (a==0) { cout &lt;&lt; 0; return 0; } ll g = __gcd(a,b); a/=g; b/=g; if (a*b&lt;0) { a=-abs(a); b=abs(b); } ll integer = a/b; a-=integer*b; string sep; if (integer!=0) { cout &lt;&lt; integer; sep=&#34; &#34;; } if (a!=0) { printf(&#34;%s%d/%d&#34;,sep.c_str(),a,b); } } 4. L1-020 帅到没朋友 # 思路：这题的难点在于理解题目，没有朋友的人指的是发朋友圈只有一个人，那么那个人就没朋友，或者查询的时候查无此人，也是没有朋友。所以只要用集合把所有朋友圈人数&gt;1的人记下来，然后输出查询结果即可
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; unordered_set&lt;int&gt; people; for (int i=0;i&lt;n;i++) { int m; cin &gt;&gt; m; if (m==1) { int x; cin &gt;&gt; x; continue; } for (int j=0;j&lt;m;j++) { int x; cin &gt;&gt; x; people.insert(x); } } int m; cin &gt;&gt; m; unordered_set&lt;int&gt; query; bool has_handsome=false; string sep; for (int i=0;i&lt;m;i++) { int x; cin &gt;&gt; x; if (!query.count(x)) { if (!people.count(x)) { printf(&#34;%s%05d&#34;,sep.c_str(),x); sep=&#34; &#34;; has_handsome=true; } query.insert(x); } } if (!has_handsome) { cout &lt;&lt; &#34;No one is handsome&#34;; } } 5. L1-028 判断素数 # 思路：先特殊情况排除x&lt;2不是质数，然后再判断x==2是质数，然后再排除偶数，最后循环用奇数验证x是否为质数，坑是数范围是2的31次方，刚好不能用int(\(2^{31}-1))，得用`long long`存(\(2^{63}-1\))
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; bool is_prime(ll x) { if (x&lt;2) { return false; } if (x==2) { return true; } if ((x&amp;1)==0) { return false; } for (int i=3;i*i&lt;=x;i+=2) { if (x%i==0) { return false; } } return true; } int main() { int n; cin &gt;&gt; n; for (int i=0;i&lt;n;i++) { ll x; cin &gt;&gt; x; if (is_prime(x)) { cout &lt;&lt; &#34;Yes&#34; &lt;&lt; &#39;\n&#39;; } else { cout &lt;&lt; &#34;No&#34; &lt;&lt; &#39;\n&#39;; } } } 6. L1-032 Left-pad # 思路：先判断字符串长度和目标长度，不够就用string补齐空位，超出就用substr截取，坑就是如果你用cin读取前两个数据，那么你的cin的缓冲区会剩余一个换行符，你需要在getline读取字符串之前调用cin.ignore()忽略掉缓冲区的换行符。
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; char c; string s; cin &gt;&gt; n &gt;&gt; c; cin.ignore(); getline(cin,s); if (n&gt;=s.size()) { s=string(n-s.size(),c) + s; } else { s=s.substr(s.size()-n,n); } cout &lt;&lt; s; } 7. L1-039 古风排版 # 思路：先把字符串存到分片存到列里面，当然可以用substr，我懒就直接遍历字符串了，然后reverse反转一下，最后在按照格式打印就行了，坑就是每列的字符数不够要补空格不然会吃WA
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; string s; cin.ignore(); getline(cin,s); vector&lt;string&gt; column; string s2; for (int i=0;i&lt;s.size();i++) { s2+=s[i]; if (s2.size()==n) { column.push_back(s2); s2=&#34;&#34;; } } if (s2!=&#34;&#34;) { column.push_back(s2); } reverse(column.begin(),column.end()); for (int r=0;r&lt;n;r++) { for (int c=0;c&lt;column.size();c++) { if (r&gt;=column[c].size()) { cout &lt;&lt; &#34; &#34;; } else { cout &lt;&lt; column[c][r]; } } cout &lt;&lt; &#39;\n&#39;; } } 8. L1-043 阅览室 # 思路：模拟，没啥难的。坑是输入可能有问题，所以结束的书要及时erase掉，还有round(double,double)返回值还是double要转为int不然格式化会出事233
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; int day=0; unordered_map&lt;int,int&gt; books; int t=0,p=0; for (;;) { int id,h,m; char c; cin &gt;&gt; id &gt;&gt; c; scanf(&#34;%d:%d&#34;,&amp;h,&amp;m); if (id==0) { day++; if (p==0) { printf(&#34;0 0\n&#34;); } else { printf(&#34;%d %d\n&#34;,p,int(round(t*1.0/p))); } t=0; p=0; if (day==n) { break; } continue; } if (c==&#39;S&#39;) { books[id] = h*60+m; } else { if (books.count(id)) { p++; t+=(h*60+m)-books[id]; books.erase(id); } } } } 9. L1-046 整除光棍 # 思路：看数据范围应该是高精度，直接无脑选Python，注意Python的整除是//
x=int(input()) n=1 c=1 while n%x!=0: n*=10 n+=1 c+=1 print(n//x,c) 10. L1-049 天梯赛座位分配 # 思路：给每个学校都准备个vector表示每个学校的座位，然后把这些vector打包塞进一个vector表示所有学校，然后主循环中维护变量i表示每个学校对应的座位索引，还有变量seat表示座位号，遍历学校vector，通过i给每个学校相同队伍位置赋值seat，每赋值一次seat++，直到只剩一个学校seat+=2，最后输出结果。坑没多少，但是大模拟很考验耐心，慢慢调试。
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; vector&lt;vector&lt;int&gt;&gt; school; for (int i=0;i&lt;n;i++) { int k; cin &gt;&gt; k; vector&lt;int&gt; seat(k*10); school.push_back(seat); } int remain_school=n; int seat=1; for (int i=0;remain_school&gt;0;i++;) { for (auto &amp;s:school) { if (i&lt;s.size()) { s[i]=seat; if (remain_school==1) { seat+=2; } else { seat++; } if (i==s.size()-1) { remain_school--; } } } } int id=1; for (auto &amp;s:school) { printf(&#34;#%d\n&#34;,id); string sep; for (int i=0;i&lt;s.size();i++) { cout &lt;&lt; sep &lt;&lt; s[i]; sep=&#34; &#34;; if (i%10==9) { sep=&#34;&#34;; cout &lt;&lt; &#39;\n&#39;; } } id++; } } 11. L1-050 倒数第N个字符串 (⭐155学长推荐) # 思路：使用26进制做，类比10机制，a=0，z=25，每26进1，也就是z+1=aa。首先用for循环构建一个有l个z的26进制数x，然后减去n-1(因为是倒数第n个数，所以要减一，因为倒数第一就是x)，然后使用do-while (x&gt;0)把结果拆开转为字符存进字符串，这样子构建的字符串是倒着的，你可以倒序输出也可以像我一样直接用reverse反转，最后记得要用a补位，保证输出长度也是l
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { ll l,n; cin &gt;&gt; l &gt;&gt; n; ll x=0; for (int i=0;i&lt;l;i++) { x*=26; x+=25; } x-=n-1; string s; do { s+=char(x%26+&#39;a&#39;); x/=26; } while (x&gt;0); reverse(s.begin(),s.end()); cout &lt;&lt; string(l-s.size(),&#39;a&#39;)+s; } 12. L1-054 福到了 # 思路：创建一个vector&lt;vector&lt;bool&gt;&gt;记录有字符的格子，注意要读取的格子包含空格所以必须用getchar不能用cin，因为cin会跳过所有空白符，因为getchar会读取\n所以我们用一个do-while循环来跳过\n，然后我们用new[i][j]=old[n-1-i][n-i-j]来180度翻转二维容器，因为vector有==的运算符重载，所以我们可以直接用==比较翻转前后两个vector是否相等，最后输出即可。
变换类型 公式 示例 (3×3) 顺时针90° new[i][j] = old[n-1-j][i] 1 2 3 → 7 4 1
4 5 6 → 8 5 2
7 8 9 → 9 6 3 逆时针90° new[i][j] = old[j][n-1-i] 1 2 3 → 3 6 9
4 5 6 → 2 5 8
7 8 9 → 1 4 7 180°旋转 new[i][j] = old[n-1-i][n-1-j] 1 2 3 → 9 8 7
4 5 6 → 6 5 4
7 8 9 → 3 2 1 水平镜像 new[i][j] = old[i][n-1-j] 1 2 3 → 3 2 1
4 5 6 → 6 5 4
7 8 9 → 9 8 7 垂直镜像 new[i][j] = old[n-1-i][j] 1 2 3 → 7 8 9
4 5 6 → 4 5 6
7 8 9 → 1 2 3 #include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { char c; int n; cin &gt;&gt; c &gt;&gt; n; vector&lt;vector&lt;bool&gt;&gt; g(n,vector&lt;bool&gt;(n)); for (auto &amp;row:g) { for (auto &amp;&amp;col:row) { char x; do { x=getchar(); } while (x==&#39;\n&#39;); col = x==&#39;@&#39;; } } vector&lt;vector&lt;bool&gt;&gt; d(n,vector&lt;bool&gt;(n)); for (int i=0;i&lt;n;i++) { for (int j=0;j&lt;n;j++) { d[i][j]=g[n-1-i][n-1-j]; } } if (g==d) { cout &lt;&lt; &#34;bu yong dao le&#34; &lt;&lt; &#39;\n&#39;; } for (auto &amp;row:d) { for (auto &amp;&amp;col:row) { cout &lt;&lt; (col?c:&#39; &#39;); } cout &lt;&lt; &#39;\n&#39;; } } 13. L1-058 6翻了 # 思路：用正则表达式替换掉9个以上的连续6为27，然后替换掉3个以上的连续6为9，注意替换顺序
import re s=input() s=re.sub(&#34;6{10,}&#34;,&#34;27&#34;,s) s=re.sub(&#34;6{4,9}&#34;,&#34;9&#34;,s) print(s) 14. L1-064 估值一亿的AI核心代码 # 思路：字符串处理首先想Python用正则表达式，不然会被恶心死，当然这题就算你用正则表达式也会被恶心。首先要先把字符串转为小写，这里按照题目要求排除I，然后处理空格，利用正则表达式删除所有不符合要求的空格，然后把2个以上的空格替换为1个空格，然后匹配I和me换位__you，注意不能直接换成you，可能会和下面的can you冲突，然后匹配完can you再把__you换回去
正则表达式 替换为 作用描述 r&quot;^ +&quot; &quot;&quot; 删除字符串开头的所有空格 r&quot; +$&quot; &quot;&quot; 删除字符串末尾的所有空格 r&quot; +(?=[!?.:'])&quot; &quot;&quot; 删除标点符号(!?.:')前的所有空格 r&quot; {2,}&quot; &quot; &quot; 将两个或更多连续空格替换为单个空格 r&quot;\b(I|me)\b&quot; &quot;__you&quot; 将单词&quot;I&quot;或&quot;me&quot;临时替换为&quot;__you&quot; r&quot;\bcan you\b&quot; &quot;I can&quot; 将&quot;can you&quot;转换为&quot;I can&quot; r&quot;\bcould you\b&quot; &quot;I could&quot; 将&quot;could you&quot;转换为&quot;I could&quot; &quot;__you&quot; &quot;you&quot; 将临时标记&quot;__you&quot;恢复为&quot;you&quot; import re n=int(input()) for _ in range(n): s=input() print(s) s=s.replace(&#34;?&#34;,&#34;!&#34;) s = &#34;&#34;.join([ i.lower() if i!=&#39;I&#39; else i for i in s]) s=re.sub(r&#34;^ +| +$| +(?=[!?.:&#39;])&#34;,&#34;&#34;,s) s=re.sub(r&#34; {2,}&#34;,&#34; &#34;,s) s=re.sub(r&#34;\b(I|me)\b&#34;,&#34;__you&#34;,s) s=re.sub(r&#34;\bcan you\b&#34;,&#34;I can&#34;,s) s=re.sub(r&#34;\bcould you\b&#34;,&#34;I could&#34;,s) s=s.replace(&#34;__you&#34;,&#34;you&#34;) print(&#34;AI:&#34;,s) 15. L1-071 前世档案 # 思路：发现每回答一次n，结论增加\(2^{层数-1}\)，所以就很简单了
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n,m; cin &gt;&gt; n &gt;&gt; m; for (int i=0;i&lt;m;i++) { int ans=1; for (int j=n-1;j&gt;=0;j--) { char c; cin &gt;&gt; c; if (c==&#39;n&#39;) { ans+=pow(2,j); } } cout &lt;&lt; ans &lt;&lt; &#39;\n&#39;; } } 16. L1-072 刮刮彩票 # 思路：又是一题超级烦人大模拟，首先应该先读取初始棋盘，但是有个坑，就是有一个0需要你填出来，可以先记一下0的位置，然后求一下和，最后用45-和就是0的点数，还有个坑就是求列的点数和的时候得d-3-1，最后建个unordered_map映射点数和金币(傻逼)
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; unordered_map&lt;int,int&gt; coins = { {6,10000},{7,36},{8,720},{9,360},{10,80},{11,252},{12,108}, {13,72},{14,54},{15,180},{16,72},{17,180},{18,119},{19,36}, {20,306},{21,1080},{22,114},{23,1800},{24,3600} }; int main() { int g[3][3]; int init_x,init_y,sum=0; for (int r=0;r&lt;3;r++) { for (int c=0;c&lt;3;c++) { int x; cin &gt;&gt; x; g[r][c]=x; sum+=x; if (x==0) { init_x=r; init_y=c; } } } g[init_x][init_y]=45-sum; for (int i=0;i&lt;3;i++) { int x,y; cin &gt;&gt; x &gt;&gt; y; x--; y--; cout &lt;&lt; g[x][y] &lt;&lt; &#39;\n&#39;; } int d,p=0; cin &gt;&gt; d; if (d&lt;=3) { for (int c=0;c&lt;3;c++) { p+=g[d-1][c]; } } else if (d&lt;=6) { for (int r=0;r&lt;3;r++) { p+=g[r][d-1-3]; } } else if (d==7) { for (int i=0;i&lt;3;i++) { p+=g[i][i]; } } else { for (int i=0;i&lt;3;i++) { p+=g[i][3-1-i]; } } cout &lt;&lt; coins[p]; } 17. L1-087 机工士姆斯塔迪奥 # 思路：首先创建图格vector&lt;vector&lt;bool&gt;&gt;存储地图，然后读取输入来将被炸的格子设为不安全，最后遍历整个地图，统计所有安全的图格
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n,m,q; cin &gt;&gt; n &gt;&gt; m &gt;&gt; q; vector&lt;vector&lt;bool&gt;&gt; g(n,vector&lt;bool&gt;(m)); for (int i=0;i&lt;q;i++) { bool column; int p; cin &gt;&gt; column &gt;&gt; p; p--; if (column) { for (int j=0;j&lt;n;j++) { g[j][p]=true; } } else { for (int j=0;j&lt;m;j++) { g[p][j]=true; } } } int res=0; for (int i=0;i&lt;n;i++) { for (int j=0;j&lt;m;j++) { if (!g[i][j]) { res++; } } } cout &lt;&lt; res; } 18. L1-088 静静的推荐 # 思路：用map&lt;int,pair&lt;int,int&gt;&gt;存储天梯赛分数和PTA分数，其中PTA达标的和没达标的分开存到pair&lt;int,int&gt;中，输入时忽略天梯赛分数低于175分的学生(斩杀线)，然后遍历整个map，其中PTA分数达标的学生无论K够不够都可以直接被录取，所以直接res+=p.second.first;，PTA分数没达标的学生只能在K论中按照成绩被录取，所以去k和人数的最小值即res+=min(k,p.second.second);，注意这题使用模拟会直接超时，坑死了
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n,k,s; cin &gt;&gt; n &gt;&gt; k &gt;&gt; s; map&lt;int,pair&lt;int,int&gt;&gt; stu; for (int i=0;i&lt;n;i++) { int gplt,pta; cin &gt;&gt; gplt &gt;&gt; pta; if (gplt&lt;175) { continue; } if (pta&gt;=s) { stu[gplt].first++; } else { stu[gplt].second++; } } int res=0; for (auto &amp;p:stu) { res+=min(k,p.second.second); res+=p.second.first; } cout &lt;&lt; res; } 19. L1-094 剪切粘贴 # 思路：烦人的字符串模拟题，先把输入坐标转化为数组下标，开始位置-1、结束位置不变，不然处理起来会乱掉，然后就是按照要求去截取字符串，然后插入到对应位置，注意这里不要先找插入位置的前s1或后s2，应该把插入位置前后相加s1+s2再找，然后得到插入位置前的起始下标p(s1)，然后把p+len(s1)就是我们cut插入的起始下标，最后合并即可s=s[:p+len(s1)] + cut + s[p+len(s1):]，这里推荐用题目给的abfg调试，测试用例的数据太长了，可以最后验证，但是别拿来调试
s=input() n=int(input()) for _ in range(n): x,y,s1,s2=input().split() x=int(x)-1 y=int(y) cut=s[x:y] s=s[:x]+s[y:] p=s.find(s1+s2) if p==-1: s+=cut else: s=s[:p+len(s1)] + cut + s[p+len(s1):] print(s) 20. L1-095 分寝室 # 思路：又是模拟模拟模拟，所以就按照题目要求模拟就行了，建一个for循环i0表示女生宿舍人数，i1=n-i0表示男生宿舍，按照题目要求筛选，复杂度是O(n)不算太慢可以接受，但是要注意条件，i1和i0是宿舍数，宿舍人数要另外算，别搞错了
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n0,n1,n; cin &gt;&gt; n0 &gt;&gt; n1 &gt;&gt; n; int min_abs=INT_MAX,min_i0=0; for (int i0=1;i0&lt;n;i0++) { if (n0%i0!=0) { continue; } if (n0==i0) { continue; } int i1=n-i0; if (n1%i1!=0) { continue; } if (n1==i1) { continue; } int abs_diff=abs(n1/i1-n0/i0); if (abs_diff&lt;min_abs) { min_abs=abs_diff; min_i0=i0; } } if (min_abs==INT_MAX) { cout &lt;&lt; &#34;No Solution&#34;; } else { cout &lt;&lt; min_i0 &lt;&lt; &#34; &#34; &lt;&lt; n-min_i0; } } 21. L1-101 别再来这么多猫娘了！ # 思路：遍历违禁词，然后用count统计该违禁词出现次数，然后用replace替换成____防止违禁词冲突，最后把____换回&lt;censored&gt;
