class Solution { public: int maxSubArray(vector&lt;int&gt;&amp; nums) { int sum=0; int max_sum=INT_MIN; for (int i=0;i&lt;nums.size();i++) { sum+=nums[i]; if (sum&gt;max_sum) { max_sum=sum; } if (sum&lt;=0) { sum=0; } } return max_sum; } }; 3. 兔子试毒 # 思路：兔子只有死和活两种信息，所以这题其实考的是把毒药瓶数的二进制数，二进制数有几位就需要几只兔子，也就是用兔子的活1死0编码表示毒药的编号101
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; int main() { int n; cin &gt;&gt; n; cout &lt;&lt; ceil(log2(n)); } 4. 淹没岛屿 # 思路：自己做的疯狂WA，这个是哈基米写的，我的思路是先统计初始岛屿数量，再沉默临海陆地，然后再统计一次，但是好像哪里有逻辑错误一直WA，求助哈基米得到了更好的解。哈基米的思路是，默认岛屿会淹没(is_sinking=true)，当dfs找到一个完全内陆的陆地，说明岛屿不会淹没(is_sinking=false)，所以直接就可以求出sunk_count，而不需要前后对减
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; const int MAXN = 1005; vector&lt;vector&lt;int&gt;&gt; g(MAXN, vector&lt;int&gt;(MAXN)); int n; void dfs(int x, int y,bool&amp; is_sinking) { if (x &lt; 0 || x &gt;= n || y &lt; 0 || y &gt;= n) return; if (g[x][y] != 1) return; g[x][y] = -1; int dx[] = {0, 0, 1, -1}; int dy[] = {1, -1, 0, 0}; bool is_border = false; for (int i = 0; i &lt; 4; ++i) { int nx = x + dx[i]; int ny = y + dy[i]; if (nx &gt;= 0 &amp;&amp; nx &lt; n &amp;&amp; ny &gt;= 0 &amp;&amp; ny &lt; n) { if (g[nx][ny] == 0) { is_border = true; break; } } } if (!is_border) { is_sinking = false; } dfs(x + 1, y, is_sinking); dfs(x - 1, y, is_sinking); dfs(x, y + 1, is_sinking); dfs(x, y - 1, is_sinking); } int main() { cin &gt;&gt; n; for (int i = 0; i &lt; n; i++) { for (int j = 0; j &lt; n; j++) { char ch; cin &gt;&gt; ch; if (ch == &#39;.&#39;) g[i][j] = 0; if (ch == &#39;#&#39;) g[i][j] = 1; } } int sunk_count = 0; for (int i = 0; i &lt; n; i++) { for (int j = 0; j &lt; n; j++) { if (g[i][j] == 1) { bool is_sinking = true; dfs(i, j, is_sinking); if (is_sinking) sunk_count++; } } } cout &lt;&lt; sunk_count &lt;&lt; endl; } 5. 质因数分解 # 思路：先计算出2-n的每一个质数存进vector&lt;int&gt; primes，注意我们不需要求阶乘（long long不够用，会直接溢出WA），我们只需要求出每个阶乘因数x的质因数然后合并进结果即可，我们遍历primes，然后找到x的质因数，然后x/=质因数并且重置循环开始下一轮查找，直到x==1结束循环
#include &lt;bits/stdc++.h&gt; using namespace std; using ll = long long; bool is_prime(ll x) { if (x&lt;2) { return false; } if (x==2) { return true; } if ((x&amp;1)==0) { return false; } for (int i=3;i*i&lt;=x;i+=2) { if (x%i==0) { return false; } } return true; } vector&lt;int&gt; primes; void get_prime_factor(map&lt;int,int&gt;&amp; nums,int x) { for (int i=0;i&lt;primes.size();i++) { ll prime=primes[i]; if (x%prime==0) { nums[prime]++; x/=prime; i=-1; } if (x==1) { break; } } } int main() { int n; cin &gt;&gt; n; for (ll i=2;i&lt;=n;i++) { if (is_prime(i)) { primes.push_back(i); } } map&lt;int,int&gt; nums; for (int i=2;i&lt;=n;i++) { get_prime_factor(nums,i); } for (auto&amp; i:nums) { printf(&#34;%d %d\n&#34;,i.first,i.second); } } 6. 螺旋矩阵 # 思路：从4个方向循环转圈圈就OK了，定义一个方向朝那个方向遍历，遍历过的数字标记为INT_MIN，遇到边界或者标记过的数就切换方向，直到遍历完所有数。这里有个技巧，就是设置两个控制x，y方向的数组，可以大幅简化代码
class Solution { public: vector&lt;int&gt; spiralOrder(vector&lt;vector&lt;int&gt;&gt;&amp; matrix) { vector&lt;int&gt; res; int n=matrix.size(); int m=matrix[0].size(); int dir=0; int dx[4]={0, 1, 0, -1}; int dy[4]={1, 0, -1, 0}; int x=0,y=0; for (int i=0;i&lt;n*m;i++) { res.push_back(matrix[x][y]); matrix[x][y]=INT_MIN; int next_x=x+dx[dir]; int next_y=y+dy[dir]; if (next_x&gt;=n||next_x&lt;0||next_y&gt;=m||next_y&lt;0||matrix[next_x][next_y]==INT_MIN) { dir=(dir+1)%4; next_x=x+dx[dir]; next_y=y+dy[dir]; } x=next_x; y=next_y; } return res; } }; 7. 插队 # 思路：从后往前找到第一个武力值&gt;=k的人直接输出并break就OK了
